<?php
require __DIR__ . '/layout.php';
$pdo = db();
$today = date('Y-m-d');
$week = date('Y-m-d', strtotime('+7 days'));
$active = (int) $pdo->query("SELECT COUNT(*) FROM prospects WHERE status NOT IN ('Closed – Won','Closed – Not Pursuing')")->fetchColumn();
$todayStatement = $pdo->prepare("SELECT COUNT(*) FROM prospects WHERE follow_up_date = ? AND status NOT IN ('Closed – Won','Closed – Not Pursuing')");
$todayStatement->execute([$today]);
$dueToday = (int) $todayStatement->fetchColumn();
$stmt = $pdo->prepare("SELECT COUNT(*) FROM prospects WHERE follow_up_date BETWEEN ? AND ? AND status NOT IN ('Closed – Won','Closed – Not Pursuing')"); $stmt->execute([$today, $week]); $dueWeek = (int) $stmt->fetchColumn();
$byStatus = $pdo->query("SELECT status, COUNT(*) total FROM prospects GROUP BY status ORDER BY FIELD(status, 'Researching','Draft Saved','Ready to Send','Sent Manually','Replied','In Discussion','Closed – Won','Closed – Not Pursuing')")->fetchAll();
$byType = $pdo->query("SELECT opportunity_type, COUNT(*) total FROM prospects GROUP BY opportunity_type ORDER BY total DESC")->fetchAll();
$followUps = $pdo->prepare("SELECT id, prospect, follow_up_date, status, recommended_next_step FROM prospects WHERE follow_up_date <= ? AND status NOT IN ('Closed – Won','Closed – Not Pursuing') ORDER BY follow_up_date ASC LIMIT 10"); $followUps->execute([$week]);
$replies = $pdo->query("SELECT p.id, p.prospect, p.reply_summary, p.last_contact FROM prospects p WHERE p.status IN ('Replied','In Discussion') OR p.reply_summary <> '' ORDER BY p.last_contact DESC, p.updated_at DESC LIMIT 8")->fetchAll();
page_start('Dashboard', 'dashboard'); ?>
<div class="page-head"><div><h1>Partnerships dashboard</h1><p>A practical view of Kikku’s active partnership pipeline.</p></div><a class="button" href="prospect.php">+ Add prospect</a></div>
<section class="cards"><div class="card"><small>Active prospects</small><div class="metric"><?= $active ?></div></div><div class="card"><small>Follow-ups today</small><div class="metric"><?= $dueToday ?></div></div><div class="card"><small>Due this week</small><div class="metric"><?= $dueWeek ?></div></div><div class="card"><small>Total prospects</small><div class="metric"><?= (int) $pdo->query('SELECT COUNT(*) FROM prospects')->fetchColumn() ?></div></div></section>
<div class="two"><section class="panel"><h2>Pipeline by status</h2><div class="stack"><?php foreach ($byStatus as $row): ?><div class="row"><?= status_badge($row['status']) ?><strong><?= (int) $row['total'] ?></strong></div><?php endforeach; ?><?php if (!$byStatus): ?><p class="empty">Import your first prospects to see the pipeline.</p><?php endif; ?></div></section><section class="panel"><h2>Opportunity mix</h2><div class="stack"><?php foreach ($byType as $row): ?><div class="row"><span><?= e($row['opportunity_type']) ?></span><strong><?= (int) $row['total'] ?></strong></div><?php endforeach; ?><?php if (!$byType): ?><p class="empty">Paid, strategic and value-exchange opportunities will appear here.</p><?php endif; ?></div></section></div>
<div class="two"><section class="panel"><h2>Follow-ups due</h2><div class="stack"><?php foreach ($followUps as $item): ?><div class="row"><div><a href="<?= e(prospect_url((int) $item['id'])) ?>"><?= e($item['prospect']) ?></a><div class="muted"><?= e($item['recommended_next_step'] ?: 'No next step recorded') ?></div></div><div><strong><?= e($item['follow_up_date']) ?></strong><br><?= status_badge($item['status']) ?></div></div><?php endforeach; ?><?php if (!$followUps->rowCount()): ?><p class="empty">Nothing due in the next seven days.</p><?php endif; ?></div></section><section class="panel"><h2>Recent replies</h2><div class="stack"><?php foreach ($replies as $item): ?><div class="row"><div><a href="<?= e(prospect_url((int) $item['id'])) ?>"><?= e($item['prospect']) ?></a><div class="muted"><?= e(mb_strimwidth($item['reply_summary'] ?: 'Reply recorded', 0, 100, '…')) ?></div></div><span class="muted"><?= e($item['last_contact'] ?: '') ?></span></div><?php endforeach; ?><?php if (!$replies): ?><p class="empty">Replies will appear here once recorded.</p><?php endif; ?></div></section></div>
<?php page_end();
